def f(n):
    if n <= 1:
        return 1
    return f(n // 2) + 1
print(f(8))

calls = 0
memo = {}
def fib(n):
    global calls
    calls += 1
    if n <= 1:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1) + fib(n - 2)
    return memo[n]
print(fib(5), calls)

